-- =============================================================================
-- P02 Training Management: approved PostgreSQL schema
-- =============================================================================
-- STATUS: APPROVED AND IMPLEMENTED by Flyway migration V1, applied to p02_training.
--         This is a reference copy. Do not run it, and do not edit it to change the schema.
--
-- The statements are identical to
-- src/main/resources/db/migration/V1__create_initial_schema.sql, apart from comments.
-- V1 is immutable, so every schema change needs a new migration, such as V2.
--
-- Greenfield design derived from docs/P02-Training-Management-Specification.docx.
-- D01-D22 are treated as confirmed business requirements.
-- Read with database-design.md, database-decision-package.md and
-- database-ambiguities.md.
--
-- Column comments use two letters: <existence>/<definition>
--   Existence:   S  the spec names this data item
--                I  not named, but the spec's flows require it
--                A  added by a decision you approved
--                C  still open, needs confirmation
--   Definition (type, nullability, default):
--                S  the spec states the type
--                I  derived from the spec's validation rules or flows
--                A  set by a decision you approved
--                T  technical default applied; no business behaviour implied
--                C  still open: the value is a draft, not a decision
-- Constraint comments:
--   [S]  the spec states this rule or constraint
--   [I]  the spec states the rule in a flow; enforcing it in the database is inferred
--   [A]  set by a decision you approved
--   [T]  technical default applied
--   [C]  draft only, business decision still open
-- A-xx references point to database-ambiguities.md.
--
-- Scope is the 13 tables below (A-02).
-- Unresolved business rules touching this file follow the literal spec:
--   A-08 cancel_deadline: D05 limit applied to the Vietnam date
--   A-15 credits, duration_hours (INT) and topic (nullable)
--   A-27 the proposed total_score CHECK is deliberately NOT applied
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. users (spec: User). Accounts, roles, login state, session revocation.
-- -----------------------------------------------------------------------------
CREATE TABLE users (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- S/A A-04
    username            VARCHAR(50)  NOT NULL,                    -- S/I
    email               VARCHAR(255) NOT NULL,                    -- S/T A-15
    password_hash       VARCHAR(60)  NOT NULL,                    -- S/I bcrypt
    full_name           VARCHAR(255) NOT NULL,                    -- S/T A-15
    role                VARCHAR(20)  NOT NULL,                    -- S/I A-05
    is_active           BOOLEAN      NOT NULL DEFAULT TRUE,       -- S/A A-16
    failed_login_count  INT          NOT NULL DEFAULT 0,          -- S/I
    locked_until        TIMESTAMPTZ,                              -- S/S
    token_version       INT          NOT NULL DEFAULT 0,          -- S/S
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),      -- A/A A-22
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),      -- A/A A-22

    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT ck_users_role CHECK (role IN                       -- [I] D04
        ('TRAINING_ADMIN', 'TRAINING_MANAGER', 'INSTRUCTOR', 'STUDENT'))
);
CREATE UNIQUE INDEX uq_users_username_lower ON users (LOWER(username));  -- [S] TR01 duplicates, case-insensitive lookup
CREATE UNIQUE INDEX uq_users_email_lower    ON users (LOWER(email));     -- [A] TR01 duplicates; case-insensitive, A-17
CREATE INDEX ix_users_role_active ON users (role, is_active);            -- [I] TR01 list, LAST_ADMIN


-- -----------------------------------------------------------------------------
-- 2. student (spec: Student). Student profile linked to an account.
-- -----------------------------------------------------------------------------
CREATE TABLE student (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- S/A A-04
    user_id         BIGINT      NOT NULL,                     -- I/I
    student_code    VARCHAR(30) NOT NULL,                     -- S/T A-15
    date_of_birth   DATE,                                     -- S/I not required at creation
    homeroom_class  VARCHAR(50),                              -- S/T A-14
    status          VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',    -- S/A A-16
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22

    CONSTRAINT pk_student PRIMARY KEY (id),
    CONSTRAINT uq_student_user UNIQUE (user_id),              -- [I] D04, TR01, TR10
    CONSTRAINT uq_student_code UNIQUE (student_code),         -- [S] TR04
    CONSTRAINT fk_student_user FOREIGN KEY (user_id) REFERENCES users (id),
    CONSTRAINT ck_student_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'INACTIVE'))  -- [I] TR04
);


-- -----------------------------------------------------------------------------
-- 3. instructor (spec: Instructor). Instructor profile linked to an account.
-- -----------------------------------------------------------------------------
CREATE TABLE instructor (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- S/A A-04
    user_id          BIGINT      NOT NULL,                     -- I/I
    instructor_code  VARCHAR(30) NOT NULL,                     -- S/T A-15
    department       VARCHAR(100),                             -- S/T A-14
    phone            VARCHAR(20),                              -- S/T A-14
    is_active        BOOLEAN     NOT NULL DEFAULT TRUE,        -- S/A A-16
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22

    CONSTRAINT pk_instructor PRIMARY KEY (id),
    CONSTRAINT uq_instructor_user UNIQUE (user_id),            -- [I] D04, TR01
    CONSTRAINT uq_instructor_code UNIQUE (instructor_code),    -- [S] TR03
    CONSTRAINT fk_instructor_user FOREIGN KEY (user_id) REFERENCES users (id)
);


-- -----------------------------------------------------------------------------
-- 4. course (spec: Course). Course catalog, default thresholds and weights.
-- -----------------------------------------------------------------------------
CREATE TABLE course (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- S/A A-04
    code                VARCHAR(20)  NOT NULL,                    -- S/I
    name                VARCHAR(150) NOT NULL,                    -- S/I
    credits             INT          NOT NULL,                    -- S/C A-15: whole numbers unconfirmed
    duration_hours      INT          NOT NULL,                    -- S/C A-15: whole numbers unconfirmed
    min_attendance_pct  NUMERIC(5,2) NOT NULL DEFAULT 80,         -- S/T default D13, type A-15
    pass_score          NUMERIC(4,2) NOT NULL DEFAULT 5.0,        -- S/T default D13, type A-15
    midterm_weight      NUMERIC(3,2) NOT NULL DEFAULT 0.40,       -- S/S
    final_weight        NUMERIC(3,2) NOT NULL DEFAULT 0.60,       -- S/S
    is_active           BOOLEAN      NOT NULL DEFAULT TRUE,       -- S/A A-16
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),      -- A/A A-22
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),      -- A/A A-22

    CONSTRAINT pk_course PRIMARY KEY (id),
    CONSTRAINT uq_course_code UNIQUE (code),                                     -- [S] TR02
    CONSTRAINT ck_course_weights_sum CHECK (midterm_weight + final_weight = 1),  -- [S] 2.1
    CONSTRAINT ck_course_midterm_weight CHECK (midterm_weight BETWEEN 0 AND 1),  -- [I] TR02
    CONSTRAINT ck_course_final_weight CHECK (final_weight BETWEEN 0 AND 1),      -- [I] TR02
    CONSTRAINT ck_course_credits CHECK (credits > 0),                            -- [I] TR02
    CONSTRAINT ck_course_duration CHECK (duration_hours > 0),                    -- [I] TR02
    CONSTRAINT ck_course_min_attendance CHECK (min_attendance_pct BETWEEN 0 AND 100),  -- [I] TR02
    CONSTRAINT ck_course_pass_score CHECK (pass_score BETWEEN 0 AND 10)                -- [I] TR02
);


-- -----------------------------------------------------------------------------
-- 5. instructor_course (spec: InstructorCourse). Courses an instructor may teach.
--    No created_at or updated_at: TR03 replaces rows as a set and never updates them.
-- -----------------------------------------------------------------------------
CREATE TABLE instructor_course (
    instructor_id  BIGINT NOT NULL,  -- S/I
    course_id      BIGINT NOT NULL,  -- S/I

    CONSTRAINT pk_instructor_course PRIMARY KEY (instructor_id, course_id),  -- [T] A-11
    CONSTRAINT fk_ic_instructor FOREIGN KEY (instructor_id) REFERENCES instructor (id),
    -- [T] A-18: TR02's only delete condition is "no ClassOffering", so these rows must not block it.
    CONSTRAINT fk_ic_course FOREIGN KEY (course_id) REFERENCES course (id) ON DELETE CASCADE
);
CREATE INDEX ix_instructor_course_course ON instructor_course (course_id);  -- [I] TR03 courseId filter


-- -----------------------------------------------------------------------------
-- 6. room (spec: Room). Rooms used by sessions.
-- -----------------------------------------------------------------------------
CREATE TABLE room (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- S/A A-04
    code        VARCHAR(30) NOT NULL,                     -- S/T A-15
    capacity    INT         NOT NULL,                     -- S/I
    is_active   BOOLEAN     NOT NULL DEFAULT TRUE,        -- S/A A-14, A-16
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22

    CONSTRAINT pk_room PRIMARY KEY (id),
    CONSTRAINT uq_room_code UNIQUE (code),               -- [S] TR06
    CONSTRAINT ck_room_capacity CHECK (capacity >= 1)    -- [I] TR06
);


-- -----------------------------------------------------------------------------
-- 7. class_offering (spec: ClassOffering). A class, its lifecycle and grading state.
-- -----------------------------------------------------------------------------
CREATE TABLE class_offering (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- S/A A-04
    class_code          VARCHAR(30)  NOT NULL,                    -- S/I
    course_id           BIGINT       NOT NULL,                    -- S/I
    semester            VARCHAR(20)  NOT NULL,                    -- S/T A-15
    start_date          DATE         NOT NULL,                    -- S/I
    end_date            DATE         NOT NULL,                    -- S/I
    instructor_id       BIGINT,                                   -- S/I NULL until assigned (TR07)
    max_capacity        INT          NOT NULL,                    -- S/I
    enrolled_count      INT          NOT NULL DEFAULT 0,          -- S/I
    status              VARCHAR(20)  NOT NULL DEFAULT 'DRAFT',    -- S/I
    cancel_deadline     TIMESTAMPTZ  NOT NULL,                    -- S/C follows D05, time of day A-08 unresolved
    cancel_reason       TEXT,                                     -- S/T A-15
    created_by          BIGINT       NOT NULL,                    -- S/I
    deleted_at          TIMESTAMPTZ,                              -- A/A A-07 kept; nothing sets it in the MVP

    -- Copied from course on publish (D13). NULL until the class is published.
    min_attendance_pct  NUMERIC(5,2),                             -- S/T A-15
    pass_score          NUMERIC(4,2),                             -- S/T A-15
    midterm_weight      NUMERIC(3,2),                             -- S/I
    final_weight        NUMERIC(3,2),                             -- S/I

    grading_status      VARCHAR(20)  NOT NULL DEFAULT 'DRAFT',    -- S/S A-05
    submitted_at        TIMESTAMPTZ,                              -- S/S
    submitted_by        BIGINT,                                   -- S/T A-12
    confirmed_at        TIMESTAMPTZ,                              -- S/S
    confirmed_by        BIGINT,                                   -- S/T A-12
    return_reason       TEXT,                                     -- S/T A-15
    grading_version     INT          NOT NULL DEFAULT 0,          -- S/A A-09 guards TR15 saves; returned as version
    started_at          TIMESTAMPTZ,                              -- S/S
    closed_at           TIMESTAMPTZ,                              -- S/S
    closed_by           BIGINT,                                   -- S/T A-12
    version             INT          NOT NULL DEFAULT 0,          -- S/A A-09 internal JPA @Version, never in a DTO
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),      -- A/A A-22
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),      -- A/A A-22

    CONSTRAINT pk_class_offering PRIMARY KEY (id),
    CONSTRAINT uq_class_offering_code UNIQUE (class_code),        -- [S] TR05
    CONSTRAINT fk_co_course FOREIGN KEY (course_id) REFERENCES course (id),
    CONSTRAINT fk_co_instructor FOREIGN KEY (instructor_id) REFERENCES instructor (id),
    CONSTRAINT fk_co_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT fk_co_submitted_by FOREIGN KEY (submitted_by) REFERENCES users (id),
    CONSTRAINT fk_co_confirmed_by FOREIGN KEY (confirmed_by) REFERENCES users (id),
    CONSTRAINT fk_co_closed_by FOREIGN KEY (closed_by) REFERENCES users (id),

    CONSTRAINT ck_co_enrolled_count CHECK (enrolled_count >= 0 AND enrolled_count <= max_capacity),  -- [S] D07, TR11
    CONSTRAINT ck_co_status CHECK (status IN                                     -- [I] 2.2
        ('DRAFT', 'OPEN', 'IN_PROGRESS', 'CLOSED', 'CANCELLED')),
    CONSTRAINT ck_co_grading_status CHECK (grading_status IN                     -- [S] 2.1
        ('DRAFT', 'SUBMITTED', 'CONFIRMED')),
    CONSTRAINT ck_co_max_capacity CHECK (max_capacity BETWEEN 1 AND 500),        -- [I] TR05
    CONSTRAINT ck_co_dates CHECK (end_date > start_date),                        -- [I] TR05
    CONSTRAINT ck_co_cancel_deadline CHECK (                                     -- [C] D05 limit on the date; A-08 unresolved
        (cancel_deadline AT TIME ZONE 'Asia/Ho_Chi_Minh')::date <= start_date),
    CONSTRAINT ck_co_snapshot_weights CHECK (                                    -- [I] copied from course
        midterm_weight IS NULL OR final_weight IS NULL OR midterm_weight + final_weight = 1),
    CONSTRAINT ck_co_snapshot_present CHECK (                                    -- [I] TR05 publish
        status NOT IN ('OPEN', 'IN_PROGRESS', 'CLOSED')
        OR (min_attendance_pct IS NOT NULL AND pass_score IS NOT NULL
            AND midterm_weight IS NOT NULL AND final_weight IS NOT NULL)),
    CONSTRAINT ck_co_instructor_present CHECK (                                  -- [I] TR05 publish
        status NOT IN ('OPEN', 'IN_PROGRESS', 'CLOSED') OR instructor_id IS NOT NULL),
    CONSTRAINT ck_co_cancel_reason CHECK (status <> 'CANCELLED' OR cancel_reason IS NOT NULL),  -- [I] D11
    CONSTRAINT ck_co_started CHECK (status NOT IN ('IN_PROGRESS', 'CLOSED') OR started_at IS NOT NULL),  -- [I] TR05
    CONSTRAINT ck_co_closed CHECK (status <> 'CLOSED' OR (closed_at IS NOT NULL AND closed_by IS NOT NULL)),  -- [I] TR16
    CONSTRAINT ck_co_closed_confirmed CHECK (status <> 'CLOSED' OR grading_status = 'CONFIRMED'),  -- [I] TR16, 2.2 diagram
    CONSTRAINT ck_co_confirmed CHECK (grading_status <> 'CONFIRMED'              -- [I] TR16
        OR (confirmed_at IS NOT NULL AND confirmed_by IS NOT NULL))
);
CREATE INDEX ix_co_course ON class_offering (course_id);                 -- [I] COURSE_IN_USE, TR09
CREATE INDEX ix_co_instructor_status ON class_offering (instructor_id, status);  -- [I] TR03, TR08, TR09, TR17
CREATE INDEX ix_co_status_start ON class_offering (status, start_date);  -- [I] TR09, TR18
CREATE INDEX ix_co_semester ON class_offering (semester);                -- [I] TR09, TR18


-- -----------------------------------------------------------------------------
-- 8. session (spec: Session). Scheduled sessions and attendance lock state.
-- -----------------------------------------------------------------------------
CREATE TABLE session (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- S/A A-04
    class_id            BIGINT  NOT NULL,                         -- I/I A-03
    session_date        DATE    NOT NULL,                         -- S/I
    start_time          TIME    NOT NULL,                         -- S/A A-06 Vietnam local
    end_time            TIME    NOT NULL,                         -- S/A A-06 Vietnam local
    room_id             BIGINT  NOT NULL,                         -- S/I
    topic               VARCHAR(200),                             -- S/C A-15: required or not is unconfirmed
    attendance_locked   BOOLEAN NOT NULL DEFAULT FALSE,           -- S/S
    locked_by           BIGINT,                                   -- S/T A-12
    locked_at           TIMESTAMPTZ,                              -- S/S
    unlock_reason       TEXT,                                     -- S/T A-15
    attendance_version  INT     NOT NULL DEFAULT 0,               -- S/S A-09 guards TR14 saves; returned as version
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22

    CONSTRAINT pk_session PRIMARY KEY (id),
    CONSTRAINT fk_session_class FOREIGN KEY (class_id) REFERENCES class_offering (id),
    CONSTRAINT fk_session_room FOREIGN KEY (room_id) REFERENCES room (id),
    CONSTRAINT fk_session_locked_by FOREIGN KEY (locked_by) REFERENCES users (id),
    CONSTRAINT ck_session_time CHECK (start_time < end_time),     -- [I] TR06
    CONSTRAINT ck_session_locked CHECK (NOT attendance_locked     -- [I] TR14
        OR (locked_by IS NOT NULL AND locked_at IS NOT NULL))
);
CREATE INDEX ix_session_class_date ON session (class_id, session_date);  -- [I] TR06, TR08, TR17
CREATE INDEX ix_session_room_date ON session (room_id, session_date);    -- [I] TR08 room conflict


-- -----------------------------------------------------------------------------
-- 9. enrollment (spec: Enrollment). A student's registration in a class.
-- -----------------------------------------------------------------------------
CREATE TABLE enrollment (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- S/A A-04
    student_id    BIGINT      NOT NULL,                     -- S/I
    class_id      BIGINT      NOT NULL,                     -- S/I A-03
    status        VARCHAR(20) NOT NULL,                     -- S/I no default: set by TR10
    enrolled_at   TIMESTAMPTZ NOT NULL,                     -- S/S
    cancelled_at  TIMESTAMPTZ,                              -- S/S
    completed_at  TIMESTAMPTZ,                              -- S/A A-06 overrides TIMESTAMP in spec 2.1
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22

    CONSTRAINT pk_enrollment PRIMARY KEY (id),
    CONSTRAINT uq_enrollment_student_class UNIQUE (student_id, class_id),  -- [S] D06, TR10
    CONSTRAINT fk_enrollment_student FOREIGN KEY (student_id) REFERENCES student (id),
    CONSTRAINT fk_enrollment_class FOREIGN KEY (class_id) REFERENCES class_offering (id),
    CONSTRAINT ck_enrollment_status CHECK (status IN ('ENROLLED', 'CANCELLED', 'COMPLETED')),  -- [I] 2.3
    CONSTRAINT ck_enrollment_cancelled CHECK (          -- [I] TR05, TR10, TR12
        (status = 'CANCELLED') = (cancelled_at IS NOT NULL)),
    CONSTRAINT ck_enrollment_completed CHECK (          -- [I] TR16
        (status = 'COMPLETED') = (completed_at IS NOT NULL))
);
CREATE INDEX ix_enrollment_class_status ON enrollment (class_id, status);  -- [I] TR13-TR16, TR18


-- -----------------------------------------------------------------------------
-- 10. attendance (spec: Attendance). One record per student per session.
-- -----------------------------------------------------------------------------
CREATE TABLE attendance (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- I/A A-04, A-11
    session_id  BIGINT      NOT NULL,                     -- S/I
    student_id  BIGINT      NOT NULL,                     -- S/I
    status      VARCHAR(10) NOT NULL,                     -- S/I no default: D16 needs an explicit mark
    remarks     VARCHAR(255),                             -- S/I
    marked_by   BIGINT      NOT NULL,                     -- S/T A-12
    marked_at   TIMESTAMPTZ NOT NULL,                     -- S/S
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- A/A A-22

    CONSTRAINT pk_attendance PRIMARY KEY (id),
    CONSTRAINT uq_attendance_session_student UNIQUE (session_id, student_id),  -- [S] TR14
    CONSTRAINT fk_attendance_session FOREIGN KEY (session_id) REFERENCES session (id),
    CONSTRAINT fk_attendance_student FOREIGN KEY (student_id) REFERENCES student (id),
    CONSTRAINT fk_attendance_marked_by FOREIGN KEY (marked_by) REFERENCES users (id),
    CONSTRAINT ck_attendance_status CHECK (status IN ('PRESENT', 'ABSENT', 'LATE'))  -- [I] TR14
);


-- -----------------------------------------------------------------------------
-- 11. assessment_result (spec: AssessmentResult). Scores and outcome per enrollment.
--     The FK to enrollment guarantees a result can only exist for a real enrollment.
--     A-27 unresolved: the proposed CHECK tying total_score to both scores is NOT applied.
-- -----------------------------------------------------------------------------
CREATE TABLE assessment_result (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,      -- I/A A-04, A-11
    student_id       BIGINT       NOT NULL,                        -- S/I A-10
    class_id         BIGINT       NOT NULL,                        -- I/I A-10
    midterm_score    NUMERIC(4,2),                                 -- S/I
    final_score      NUMERIC(4,2),                                 -- S/I
    total_score      NUMERIC(4,2),                                 -- S/I
    attendance_rate  NUMERIC(5,2),                                 -- S/I
    final_status     VARCHAR(20)  NOT NULL DEFAULT 'IN_PROGRESS',  -- S/I
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),          -- A/A A-22
    updated_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),          -- A/A A-22

    CONSTRAINT pk_assessment_result PRIMARY KEY (id),
    CONSTRAINT uq_ar_student_class UNIQUE (student_id, class_id),  -- [A] A-10
    CONSTRAINT fk_ar_enrollment FOREIGN KEY (student_id, class_id)
        REFERENCES enrollment (student_id, class_id),              -- [A] A-10
    CONSTRAINT ck_ar_midterm CHECK (midterm_score BETWEEN 0 AND 10),     -- [I] TR15; NULL allowed
    CONSTRAINT ck_ar_final CHECK (final_score BETWEEN 0 AND 10),         -- [I] TR15; NULL allowed
    CONSTRAINT ck_ar_total CHECK (total_score BETWEEN 0 AND 10),         -- [I] D14
    CONSTRAINT ck_ar_attendance_rate CHECK (attendance_rate BETWEEN 0 AND 100),  -- [I] D15
    CONSTRAINT ck_ar_final_status CHECK (final_status IN ('IN_PROGRESS', 'PASSED', 'FAILED'))  -- [I] TR15, TR16
);
CREATE INDEX ix_ar_class ON assessment_result (class_id);  -- [I] TR15, TR16, TR18


-- -----------------------------------------------------------------------------
-- 12. grade_audit_log (spec: GradeAuditLog). One row per score change. Read-only API.
--     References enrollment, not assessment_result: TR15 writes this row before the
--     result upsert, so the result may not exist yet on the first score.
--     Append-only, so changed_at is its only timestamp.
-- -----------------------------------------------------------------------------
CREATE TABLE grade_audit_log (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- I/A A-04
    student_id  BIGINT      NOT NULL,                     -- S/I
    class_id    BIGINT      NOT NULL,                     -- S/I
    score_type  VARCHAR(10) NOT NULL,                     -- S/T A-19
    old_score   NUMERIC(4,2),                             -- S/I NULL on first entry (D18)
    new_score   NUMERIC(4,2),                             -- S/I NULL when a score is cleared (TR15), A-27
    changed_by  BIGINT      NOT NULL,                     -- S/T A-12
    reason      TEXT,                                     -- S/T NULL on first entry (D18), A-15
    ip_address  VARCHAR(45),                              -- S/T A-20
    changed_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- S/S

    CONSTRAINT pk_grade_audit_log PRIMARY KEY (id),
    CONSTRAINT fk_gal_enrollment FOREIGN KEY (student_id, class_id)
        REFERENCES enrollment (student_id, class_id),     -- [I] TR15
    CONSTRAINT fk_gal_changed_by FOREIGN KEY (changed_by) REFERENCES users (id),
    CONSTRAINT ck_gal_score_type CHECK (score_type IN ('MIDTERM', 'FINAL')),  -- [T] A-19
    CONSTRAINT ck_gal_old_score CHECK (old_score BETWEEN 0 AND 10),           -- [I] TR15
    CONSTRAINT ck_gal_new_score CHECK (new_score BETWEEN 0 AND 10),           -- [I] TR15
    CONSTRAINT ck_gal_reason CHECK (old_score IS NULL OR reason IS NOT NULL)  -- [I] D18
);
CREATE INDEX ix_gal_class_changed ON grade_audit_log (class_id, changed_at DESC);  -- [I] TR18
CREATE INDEX ix_gal_changed ON grade_audit_log (changed_at DESC);                  -- [I] TR18 date filter


-- -----------------------------------------------------------------------------
-- 13. app_security_log (spec: AppSecurityLog). Security and business action log.
--     No FK to users: logs must outlive what they describe and survive a rollback.
--     No CHECK on action (A-21b, approved): a rejected insert would lose a security
--     event. Values are controlled by a Java enum holding the 24 actions in spec 0.6.
--     Append-only, so created_at is its only timestamp.
-- -----------------------------------------------------------------------------
CREATE TABLE app_security_log (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY,  -- I/A A-04
    action      VARCHAR(30) NOT NULL,                     -- S/A A-21b Java enum, no CHECK
    username    VARCHAR(50),                              -- S/A A-21c existing accounts only, otherwise NULL
    ip_address  VARCHAR(45),                              -- S/T A-20
    details     JSONB,                                    -- A/A A-21a before and after values
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),       -- S/S

    CONSTRAINT pk_app_security_log PRIMARY KEY (id)
);
CREATE INDEX ix_asl_action_created ON app_security_log (action, created_at DESC);  -- [I] TR18 counts
CREATE INDEX ix_asl_created ON app_security_log (created_at DESC);                 -- [I] TR18 recent 20
